import{_ as o,o as i,c as t,ai as r}from"./chunks/framework.C33Uq6m-.js";const h=JSON.parse(`{"title":"Atelier d'Outils","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/tool-workshop.md","filePath":"fr/guide/tool-workshop.md"}`),s={name:"fr/guide/tool-workshop.md"};function n(a,e,l,u,d,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="atelier-d-outils" tabindex="-1">Atelier d&#39;Outils <a class="header-anchor" href="#atelier-d-outils" aria-label="Permalink to &quot;Atelier d&#39;Outils&quot;">​</a></h1><p>L&#39;Atelier d&#39;Outils est un canevas visuel pour créer, modifier et tester des définitions d&#39;outils que les modèles peuvent appeler pendant le chat.</p><p><strong>Élément de la barre latérale :</strong> Atelier d&#39;Outils <strong>Route :</strong> <code>/tools</code></p><h2 id="vue-d-ensemble-de-l-interface" tabindex="-1">Vue d&#39;ensemble de l&#39;interface <a class="header-anchor" href="#vue-d-ensemble-de-l-interface" aria-label="Permalink to &quot;Vue d&#39;ensemble de l&#39;interface&quot;">​</a></h2><p>La page présente un <strong>canevas à base de nœuds</strong> propulsé par Vue Flow. Chaque outil est représenté sous forme de nœud visuel affichant son nom, sa description, ses paramètres et le corps de son implémentation.</p><h2 id="creer-des-outils" tabindex="-1">Créer des outils <a class="header-anchor" href="#creer-des-outils" aria-label="Permalink to &quot;Créer des outils&quot;">​</a></h2><h3 id="a-partir-de-modeles" tabindex="-1">À partir de modèles <a class="header-anchor" href="#a-partir-de-modeles" aria-label="Permalink to &quot;À partir de modèles&quot;">​</a></h3><p>Cliquez sur <strong>Modèles</strong> pour parcourir plus de 15 modèles intégrés, notamment :</p><ul><li>Requêtes web (HTTP)</li><li>Calculatrice</li><li>Intégration Google Calendar / Gmail</li><li>Testeur de regex</li><li>Utilitaires de date/heure</li><li>Et plus encore</li></ul><h3 id="a-partir-de-zero" tabindex="-1">À partir de zéro <a class="header-anchor" href="#a-partir-de-zero" aria-label="Permalink to &quot;À partir de zéro&quot;">​</a></h3><p>Cliquez sur <strong>Ajouter un outil</strong> pour créer un nœud d&#39;outil vierge. Remplissez :</p><ul><li><strong>Nom</strong> -- Le nom de la fonction (utilisé par le modèle)</li><li><strong>Description</strong> -- Ce que fait l&#39;outil (aide le modèle à décider quand l&#39;utiliser)</li><li><strong>Paramètres</strong> -- Entrées définies en JSON Schema</li><li><strong>Implémentation</strong> -- Corps de la fonction TypeScript</li></ul><h2 id="modifier-les-outils" tabindex="-1">Modifier les outils <a class="header-anchor" href="#modifier-les-outils" aria-label="Permalink to &quot;Modifier les outils&quot;">​</a></h2><h3 id="edition-de-code-en-ligne" tabindex="-1">Édition de code en ligne <a class="header-anchor" href="#edition-de-code-en-ligne" aria-label="Permalink to &quot;Édition de code en ligne&quot;">​</a></h3><p>Chaque nœud d&#39;outil dispose d&#39;un éditeur <strong>CodeMirror 6</strong> complet avec coloration syntaxique TypeScript. Modifiez l&#39;implémentation directement sur le canevas.</p><h3 id="panneau-de-code-synchronisation-bidirectionnelle" tabindex="-1">Panneau de code (synchronisation bidirectionnelle) <a class="header-anchor" href="#panneau-de-code-synchronisation-bidirectionnelle" aria-label="Permalink to &quot;Panneau de code (synchronisation bidirectionnelle)&quot;">​</a></h3><p>Ouvrez le <strong>Panneau de code</strong> pour voir tous les outils sous forme de code source TypeScript combiné. Cela utilise un <strong>analyseur AST Recast</strong> pour une synchronisation bidirectionnelle :</p><ul><li>Modification du code dans le panneau → les nœuds se mettent à jour sur le canevas</li><li>Modification des nœuds sur le canevas → le code se met à jour dans le panneau</li></ul><h3 id="visionneuse-de-schema" tabindex="-1">Visionneuse de schéma <a class="header-anchor" href="#visionneuse-de-schema" aria-label="Permalink to &quot;Visionneuse de schéma&quot;">​</a></h3><p>Cliquez sur l&#39;icône de schéma sur n&#39;importe quel outil pour voir son <strong>schéma JSON compatible OpenAI</strong> généré automatiquement. Copie en un clic pour utilisation dans d&#39;autres systèmes.</p><h2 id="sonder-et-selectionner" tabindex="-1">Sonder et sélectionner <a class="header-anchor" href="#sonder-et-selectionner" aria-label="Permalink to &quot;Sonder et sélectionner&quot;">​</a></h2><p>Pointez vers n&#39;importe quelle URL d&#39;API pour :</p><ol><li><strong>Sonder</strong> le endpoint -- envoyer une requête et inspecter la réponse</li><li><strong>Parcourir l&#39;arborescence JSON</strong> -- développer/réduire la structure de la réponse</li><li><strong>Sélectionner des champs</strong> -- choisir les données dont vous avez besoin</li><li><strong>Générer automatiquement</strong> le code fetch et les correspondances de paramètres</li></ol><h2 id="decouverte-openapi" tabindex="-1">Découverte OpenAPI <a class="header-anchor" href="#decouverte-openapi" aria-label="Permalink to &quot;Découverte OpenAPI&quot;">​</a></h2><p>Si une API dispose d&#39;une spécification OpenAPI/Swagger :</p><ol><li>Saisissez l&#39;URL de la spécification</li><li>LLMxRay analyse la spécification automatiquement</li><li>Parcourez les endpoints disponibles</li><li>Sélectionnez un endpoint pour générer automatiquement une définition d&#39;outil</li></ol><h2 id="execution-en-direct" tabindex="-1">Exécution en direct <a class="header-anchor" href="#execution-en-direct" aria-label="Permalink to &quot;Exécution en direct&quot;">​</a></h2><p>Pendant le chat, lorsque le modèle appelle un outil :</p><ul><li>Le nœud correspondant <strong>pulse</strong> sur le canevas</li><li>Les résultats d&#39;exécution apparaissent en <strong>superposition</strong> sur le nœud</li><li>La chronologie des appels d&#39;outils (dans Diagnostics de Chat) renvoie vers le canevas</li></ul><h2 id="optimiseur-d-appels-d-outils" tabindex="-1">Optimiseur d&#39;appels d&#39;outils <a class="header-anchor" href="#optimiseur-d-appels-d-outils" aria-label="Permalink to &quot;Optimiseur d&#39;appels d&#39;outils&quot;">​</a></h2><p>Lorsqu&#39;un modèle appelle un outil pendant le chat, un bouton <strong>&quot;Optimiser cet outil&quot;</strong> apparaît sur le résultat. Cliquez dessus pour ouvrir le tiroir d&#39;optimisation des réponses :</p><ol><li><strong>Visualiser</strong> la réponse de l&#39;API sous forme d&#39;arborescence JSON interactive</li><li><strong>Sélectionner</strong> uniquement les champs dont le modèle a réellement besoin</li><li><strong>Générer automatiquement</strong> un code fetch optimisé avec extraction des champs</li><li><strong>Créer</strong> un nouvel outil optimisé dans l&#39;Atelier en un clic</li></ol><h2 id="persistance" tabindex="-1">Persistance <a class="header-anchor" href="#persistance" aria-label="Permalink to &quot;Persistance&quot;">​</a></h2><p>Les définitions d&#39;outils, positions des nœuds, correspondances et configurations de sondage sont toutes persistées et survivent aux actualisations du navigateur.</p><h2 id="exporter-les-outils" tabindex="-1">Exporter les outils <a class="header-anchor" href="#exporter-les-outils" aria-label="Permalink to &quot;Exporter les outils&quot;">​</a></h2><p>Cliquez sur le bouton <strong>Exporter</strong> pour telecharger vos definitions d&#39;outils au format <strong>JSON</strong>. L&#39;export inclut les noms, descriptions, schemas de parametres et corps d&#39;implementation -- tout ce qu&#39;il faut pour reimporter ou partager vos outils. Consultez le <a href="./export.html">guide d&#39;export</a> pour plus de details sur toutes les options d&#39;export.</p><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li>Commencez par un modèle et personnalisez-le -- c&#39;est plus rapide que de partir de zéro.</li><li>Utilisez la <strong>Visionneuse de schéma</strong> pour vérifier que votre définition d&#39;outil correspond à ce que les modèles attendent.</li><li>Le flux de travail <strong>Sonder et sélectionner</strong> est le moyen le plus rapide d&#39;encapsuler une API REST en tant qu&#39;outil.</li><li>Les outils sont automatiquement disponibles dans le chat lorsqu&#39;ils sont activés.</li></ul>',38)])])}const m=o(s,[["render",n]]);export{h as __pageData,m as default};
